const SIG_BLOB_LEN: usize = N_SLOTS * 65; // 780
const ROOT_TAIL_LEN: usize = 11;
const N_APPROVERS: usize = 10; // vault-level approver slots (unchanged from v0.4.1)

const COV_ROOT: Hash = Hash::from_bytes(*b"ROOTROOTROOTROOTROOTROOTROOTROOT");
const COV_ROOT_B: Hash = Hash::from_bytes(*b"ROOTBROOTBROOTBROOTBROOTBROOTBRO");
const COV_VAULT: Hash = Hash::from_bytes(*b"KASVLKASVLKASVLKASVLKASVLKASVLKA");
const COV_ALIEN: Hash = Hash::from_bytes(*b"ALIENALIENALIENALIENALIENALIENAL");

const ZERO32: [u8; 32] = [0u8; 32];
const ORG_ID: [u8; 32] = [0xa7u8; 32];
const ORG_ID_B: [u8; 32] = [0xb7u8; 32];
const VAULT_ID: [u8; 32] = [0x44u8; 32];
const AGENT_DOMAIN: [u8; 4] = [0x50, 0x56, 0x34, 0x01];
const RECIP_DOMAIN: [u8; 4] = [0x50, 0x56, 0x33, 0x01];

const KAS: i64 = 100_000_000;
