#[derive(Clone, PartialEq, Debug)]
struct VaultState {
    protected: i64,
    reserve: i64,
    paused: i64,
    agent_root: [u8; 32],
    approvers: [[u8; 32]; N_APPROVERS],
    approval_m: i64,
    policy_nonce: i64,
}
fn base_vault_state(agent_root: [u8; 32]) -> VaultState {
    VaultState { protected: PROTECTED, reserve: RESERVE, paused: 0, agent_root, approvers: [ZERO32; N_APPROVERS], approval_m: 0, policy_nonce: 0 }
}

/// Exact-live-state templating — same anchors the v0.4.1 production suite
/// uses; the delta generator never touches them.
fn vault_templated(src: &str, s: &VaultState) -> String {
    let mut src = src.to_string();
    let mut r = |from: String, to: String| {
        assert!(src.contains(&from), "anchor missing: {from}");
        src = src.replacen(&from, &to, 1);
    };
    r("int protectedValue = initValue;".into(), format!("int protectedValue = {};", s.protected));
    r("int feeReserve = initFeeReserve;".into(), format!("int feeReserve = {};", s.reserve));
    r("int paused = 0;".into(), format!("int paused = {};", s.paused));
    r("byte[32] agentRoot = initAgentRoot;".into(), format!("byte[32] agentRoot = 0x{};", hx(&s.agent_root)));
    for i in 0..N_APPROVERS {
        r(format!("pubkey approver{} = initApprover{};", i + 1, i + 1), format!("pubkey approver{} = 0x{};", i + 1, hx(&s.approvers[i])));
    }
    r("int approvalM = initApprovalM;".into(), format!("int approvalM = {};", s.approval_m));
    r("int policyNonce = 0;".into(), format!("int policyNonce = {};", s.policy_nonce));
    src
}

fn compile_vault(root: &RootPin, recovery_pk: &[u8; 32], s: &VaultState) -> CompiledContract<'static> {
    let src: &'static str = leak(vault_templated(src_kas_raw(), s));
    let mut args: Vec<Expr<'static>> = vec![
        Expr::bytes(VAULT_ID.to_vec()),
        Expr::bytes(root.covid.as_bytes().to_vec()),
        Expr::bytes(root.hash.to_vec()),
        Expr::int(root.prefix_len),
        Expr::int(root.state_len),
        Expr::int(root.suffix_len),
        Expr::bytes(recovery_pk.to_vec()),
        Expr::bytes(s.agent_root.to_vec()),
        Expr::int(s.reserve),
    ];
    for i in 0..N_APPROVERS {
        args.push(Expr::bytes(s.approvers[i].to_vec()));
    }
    args.push(Expr::int(s.approval_m));
    args.push(Expr::int(s.protected));
    compile_contract(src, &args, CompileOptions::default()).unwrap_or_else(|e| panic!("compile v0.7-kas: {e:?}"))
}

const APPROVER_NAMES: [&str; N_APPROVERS] =
    ["approver1", "approver2", "approver3", "approver4", "approver5", "approver6", "approver7", "approver8", "approver9", "approver10"];

fn vault_state_arg(s: &VaultState) -> Expr<'static> {
    let mut f: Vec<(&'static str, Expr<'static>)> = vec![
        ("boundVaultId", Expr::bytes(VAULT_ID.to_vec())),
        ("protectedValue", Expr::int(s.protected)),
        ("feeReserve", Expr::int(s.reserve)),
        ("paused", Expr::int(s.paused)),
        ("agentRoot", Expr::bytes(s.agent_root.to_vec())),
    ];
    for i in 0..N_APPROVERS {
        f.push((APPROVER_NAMES[i], Expr::bytes(s.approvers[i].to_vec())));
    }
    f.push(("approvalM", Expr::int(s.approval_m)));
    f.push(("policyNonce", Expr::int(s.policy_nonce)));
    struct_object(f)
}

/// Align each signer to the slot holding its sorted key (v0.4.1 pattern).
fn approver_set(keys: &[&Keypair]) -> [[u8; 32]; N_APPROVERS] {
    let mut active: Vec<[u8; 32]> = keys.iter().map(|k| xonly32(k)).collect();
    active.sort();
    let mut a = [ZERO32; N_APPROVERS];
    for (i, k) in active.iter().enumerate() {
        a[i] = *k;
    }
    a
}
fn approvals_by_key<'a>(slots: &[[u8; 32]; N_APPROVERS], signers: &[(&'a Keypair, SigHashType)]) -> [Option<(&'a Keypair, SigHashType)>; N_APPROVERS] {
    let mut ap: [Option<(&'a Keypair, SigHashType)>; N_APPROVERS] = Default::default();
    for i in 0..N_APPROVERS {
        for (s, ty) in signers {
            if xonly32(s) == slots[i] {
                ap[i] = Some((*s, *ty));
            }
        }
    }
    ap
}

/* ================================================================== */
/* vault owner operations (root + vault, ONE transaction)               */
/* ================================================================== */

#[derive(Clone, Copy, PartialEq, Debug)]
enum VaultOp {
    /// the merged entrypoint, selectors 0..6 (6 = EMERGENCY pause under FREEZE)
    Control(i64),
    Recover,
}

#[derive(Clone)]
struct VaultCase {
    op: VaultOp,
    root_prev: RootState,
    root_new: Option<RootState>,
    root_action: i64,
    root_signers: Vec<usize>,
    root_tmpl: RootTemplate,
    root_tmpl_carried: Option<RootTemplate>,
    root_tmpl_output: Option<RootTemplate>,
    root_decoy_state: Option<RootState>,
    root_covid_carried: Hash,
    root_covid_pinned: Hash,
    root_succession: Option<u8>,
    root_sequence: u64,
    vault_prev: VaultState,
    vault_new: VaultState,
    no_root: bool,
    two_roots: bool,
    alien_rider: bool,
    vault_succ_value: Option<i64>,
    recover_dest: Option<[u8; 32]>,
    wrong_root_template: bool,
    budget: u16,
}
impl VaultCase {
    fn honest(op: VaultOp) -> VaultCase {
        let root_prev = RootState::with(3, 2, 1, 2);
        // selector 6 is the EMERGENCY pause: it must ride a root FREEZE
        let (action, signers) = match op {
            VaultOp::Control(6) => (2i64, vec![0usize]),
            _ => (0i64, vec![0usize, 1usize]),
        };
        let vault_prev = base_vault_state(ZERO32);
        let vault_new = match op {
            VaultOp::Control(0) => VaultState { agent_root: [0x99; 32], policy_nonce: vault_prev.policy_nonce + 1, ..vault_prev.clone() },
            VaultOp::Control(1) => {
                let approver_keys: Vec<Keypair> = vec![kp(0x24), kp(0x25), kp(0x26)];
                let refs: Vec<&Keypair> = approver_keys.iter().collect();
                let approvers = approver_set(&refs);
                VaultState { approvers, approval_m: 2, policy_nonce: vault_prev.policy_nonce + 1, ..vault_prev.clone() }
            }
            VaultOp::Control(2) => VaultState { protected: vault_prev.protected + KAS, ..vault_prev.clone() },
            VaultOp::Control(3) => VaultState { reserve: vault_prev.reserve + KAS, ..vault_prev.clone() },
            VaultOp::Control(4) => VaultState { paused: 1, ..vault_prev.clone() },
            VaultOp::Control(5) => VaultState { paused: 0, ..vault_prev.clone() },
            VaultOp::Control(6) => VaultState { paused: 1, ..vault_prev.clone() },
            _ => vault_prev.clone(),
        };
        let vault_prev = if op == VaultOp::Control(5) { VaultState { paused: 1, ..vault_prev } } else { vault_prev };
        VaultCase {
            op,
            root_prev,
            root_new: None,
            root_action: action,
            root_signers: signers,
            root_tmpl: RootTemplate::default(),
            root_tmpl_carried: None,
            root_tmpl_output: None,
            root_decoy_state: None,
            root_covid_carried: COV_ROOT,
            root_covid_pinned: COV_ROOT,
            root_succession: None,
            root_sequence: 0,
            vault_prev,
            vault_new,
            no_root: false,
            two_roots: false,
            alien_rider: false,
            vault_succ_value: None,
            recover_dest: None,
            wrong_root_template: false,
            budget: 400,
        }
    }
}

struct VaultOutcome {
    results: Vec<Result<(), TxScriptError>>,
    units: Vec<u64>,
    tx: Transaction,
    entries: Vec<UtxoEntry>,
    vault_redeem_len: usize,
    root_redeem_len: usize,
}

fn run_vault_owner_op(c: &VaultCase) -> VaultOutcome {
    let recovery_pk = default_recovery_pk();
    let rpin_tmpl =
        if c.wrong_root_template { RootTemplate { recovery_delay: RECOVERY_DELAY + 7, ..RootTemplate::default() } } else { c.root_tmpl.clone() };
    let rpin = root_pin(c.root_covid_pinned, &rpin_tmpl);

    let vault_prev_c = compile_vault(&rpin, &recovery_pk, &c.vault_prev);
    let vault_next_c = compile_vault(&rpin, &recovery_pk, &c.vault_new);

    let carried_tmpl = c.root_tmpl_carried.clone().unwrap_or_else(|| c.root_tmpl.clone());
    let output_tmpl = c.root_tmpl_output.clone().unwrap_or_else(|| carried_tmpl.clone());
    let root_prev_c = compile_root(&c.root_prev, &carried_tmpl);
    let expect_frozen = if c.op == VaultOp::Control(6) { 1 } else { 0 };
    let root_new = c.root_new.clone().unwrap_or(RootState { frozen: expect_frozen, ..c.root_prev.advanced() });
    let root_next_c = compile_root(&root_new, &output_tmpl);

    let vault_utxo_value = c.vault_prev.protected + c.vault_prev.reserve;
    let mut entries: Vec<UtxoEntry> = vec![cov_utxo(vault_utxo_value, &vault_prev_c, COV_VAULT)];
    let mut input_ids: Vec<(u8, u64)> = vec![(1, 0)];
    let mut outputs: Vec<TransactionOutput> = vec![];

    let root_input_idx: u16 = 1;
    if !c.no_root {
        entries.push(cov_utxo(ROOT_KAS, &root_prev_c, c.root_covid_carried));
        input_ids.push((2, c.root_sequence));
    }
    let recover_dest = c.recover_dest.unwrap_or(recovery_pk);
    match c.op {
        VaultOp::Recover => outputs.push(p2pk_out(&recover_dest, vault_utxo_value)),
        _ => outputs.push(cov_out(c.vault_succ_value.unwrap_or(c.vault_new.protected + c.vault_new.reserve), &vault_next_c, 0, COV_VAULT)),
    }
    if !c.no_root {
        outputs.push(cov_out(ROOT_KAS - ROOT_FEE_PAID, &root_next_c, root_input_idx, c.root_covid_carried));
    }

    let mut second_root_idx: Option<usize> = None;
    if c.two_roots {
        second_root_idx = Some(input_ids.len());
        entries.push(cov_utxo(ROOT_KAS, &root_prev_c, c.root_covid_carried));
        input_ids.push((4, c.root_sequence));
        outputs.push(cov_out(ROOT_KAS - ROOT_FEE_PAID, &root_next_c, second_root_idx.unwrap() as u16, c.root_covid_carried));
    }
    if c.alien_rider {
        // stand-in foreign covenant family: another compiled instance of
        // this same contract, bound to a DIFFERENT covenant id (COV_ALIEN),
        // demonstrating that requireOnlyRootCovenantInputs refuses ANY
        // covenant family other than the root, not merely a specific one.
        // Its own execution result is never checked.
        let alien_state = base_vault_state([0x55; 32]);
        let alien_c = compile_vault(&rpin, &recovery_pk, &alien_state);
        let idx = input_ids.len();
        entries.push(cov_utxo(KAS, &alien_c, COV_ALIEN));
        input_ids.push((5, 0));
        outputs.push(cov_out(KAS, &alien_c, idx as u16, COV_ALIEN));
    }

    let unsigned = build_tx(input_ids.iter().map(|(id, seq)| tx_input(*id, vec![], *seq, c.budget)).collect(), outputs.clone());

    let mut sigscripts: Vec<Vec<u8>> = input_ids.iter().map(|_| vec![]).collect();
    sigscripts[0] = match c.op {
        VaultOp::Control(sel) => cov_call(&vault_prev_c, "ownerControl", vec![vault_state_arg(&c.vault_new), Expr::int(sel)]),
        VaultOp::Recover => cov_call(&vault_prev_c, "ownerRecover", vec![Vec::<Expr<'static>>::new().into()]),
    };
    if !c.no_root {
        let root_ss = match c.root_succession {
            Some(seed) => {
                let s = sign(&unsigned, &entries, 1, &kp(seed));
                cov_call(&root_prev_c, "rootSuccession", vec![root_state_arg(&root_new), Expr::bytes(s)])
            }
            None => {
                let blob = root_owner_blob(&unsigned, &entries, 1, &c.root_signers);
                let args = vec![root_state_arg(&root_new), Expr::int(c.root_action), Expr::bytes(blob)];
                match c.root_decoy_state.as_ref() {
                    Some(decoy) => {
                        let decoy_c = compile_root(decoy, &carried_tmpl);
                        cov_call_with_decoy_redeem(&root_prev_c, &decoy_c, "rootAction", args)
                    }
                    None => cov_call(&root_prev_c, "rootAction", args),
                }
            }
        };
        sigscripts[1] = root_ss;
    }
    if let Some(i) = second_root_idx {
        let blob = root_owner_blob(&unsigned, &entries, i, &c.root_signers);
        sigscripts[i] = cov_call(&root_prev_c, "rootAction", vec![root_state_arg(&root_new), Expr::int(c.root_action), Expr::bytes(blob)]);
    }

    let inputs: Vec<TransactionInput> = input_ids.iter().zip(sigscripts).map(|((id, seq), ss)| tx_input(*id, ss, *seq, c.budget)).collect();
    let tx = build_tx(inputs, outputs);

    let mut results = vec![];
    let mut units = vec![];
    for i in 0..tx.inputs.len() {
        let (r, u) = execute_input_measured(tx.clone(), entries.clone(), i);
        results.push(r);
        units.push(u);
    }
    VaultOutcome { results, units, tx, entries, vault_redeem_len: vault_prev_c.script.len(), root_redeem_len: root_prev_c.script.len() }
}

fn accept_vault(label: &str, c: &VaultCase) -> VaultOutcome {
    let o = run_vault_owner_op(c);
    for (i, r) in o.results.iter().enumerate() {
        r.as_ref().unwrap_or_else(|e| panic!("{label}: input {i} must ACCEPT the honest case: {e:?}"));
    }
    o
}
fn refuse_vault(label: &str, c: &VaultCase) -> String {
    let o = run_vault_owner_op(c);
    match &o.results[0] {
        Ok(()) => panic!("{label}: the VAULT input accepted a case that must be refused"),
        Err(e) => format!("{e:?}"),
    }
}

/* ================================================================== */
/* the root pin this vault is compiled against                         */
/* ================================================================== */

#[test]
fn v7kas_root_pin_geometry_matches_the_production_root() {
    let tmpl = RootTemplate::default();
    let pin = root_pin(COV_ROOT, &tmpl);
    for s in [
        RootState::with(1, 1, 1, 0),
        RootState::with(12, 12, 1, 6),
        RootState { frozen: 1, nonce: 1, ..RootState::with(7, 4, 2, 3) },
    ] {
        let c = compile_root(&s, &tmpl);
        let t = template_of(&c);
        assert_eq!(t.prefix.len() as i64, pin.prefix_len, "rootPrefixLen must not depend on the live state");
        assert_eq!(t.state_len as i64, pin.state_len, "rootStateLen must be CONSTANT");
        assert_eq!(t.suffix.len() as i64, pin.suffix_len, "rootSuffixLen must not depend on the live state");
        assert_eq!(t.hash, pin.hash, "rootTemplateVmHash must not depend on the live state");
        let state = &c.script[c.state_layout.start..c.state_layout.start + c.state_layout.len];
        let tail = &state[state.len() - ROOT_TAIL_LEN..];
        let mut expect = vec![0x01u8, s.frozen as u8, 0x08u8];
        expect.extend_from_slice(&num8(s.nonce));
        assert_eq!(tail, &expect[..], "the TAIL the vault rebuilds must be 0x01||frozen||0x08||nonce8");
    }
    println!(
        "[pin] rootPrefixLen {} | rootStateLen {} | rootSuffixLen {} | TAIL_LEN {} | rootTemplateVmHash {}",
        pin.prefix_len, pin.state_len, pin.suffix_len, ROOT_TAIL_LEN, hx(&pin.hash)
    );
}

