#[test]
fn v7kas_d6_frozen_recovery_cannot_authorize_a_general_owner_operation() {
    let mut c = VaultCase::honest(VaultOp::Control(4));
    c.root_prev = RootState::with(4, 4, 1, 2);
    c.root_action = 4;
    c.root_sequence = RECOVERY_DELAY as u64;
    c.root_signers = vec![0, 1];
    c.root_new = Some(RootState { frozen: 1, ..c.root_prev.advanced() });
    let err = refuse_vault("D6: frozen OWNER-RECOVER under a general vault owner operation", &c);
    println!("D6: recovery quorum can no longer authorize a general vault owner op -> REFUSED by the vault pin: {err}");

    let mut unfrozen = c.clone();
    unfrozen.root_new = Some(c.root_prev.advanced());
    let o = run_vault_owner_op(&unfrozen);
    assert!(o.results[1].is_err(), "the root must refuse an OWNER-RECOVER landing unfrozen (D6)");
    println!("D6: the same recovery landing UNFROZEN is refused by the ROOT input -> {:?}", o.results[1].as_ref().unwrap_err());
}

#[test]
fn v7kas_d6_frozen_recovery_can_still_ride_only_the_emergency_pause() {
    let mut c = VaultCase::honest(VaultOp::Control(6));
    c.root_prev = RootState::with(4, 4, 1, 2);
    c.root_action = 4;
    c.root_sequence = RECOVERY_DELAY as u64;
    c.root_signers = vec![0, 1];
    c.root_new = Some(RootState { frozen: 1, ..c.root_prev.advanced() });
    let o = run_vault_owner_op(&c);
    for (i, r) in o.results.iter().enumerate() {
        r.as_ref().unwrap_or_else(|e| panic!("D6 consequence: input {i} was expected to accept: {e:?}"));
    }
    println!("D6 CONSEQUENCE (measured): a frozen OWNER-RECOVER with an unchanged head can ride selector 6 (EMERGENCY pause) and nothing else.");
}

/* ================================================================== */
/* delegate (agent) spend — the path the root never touches            */
/* ================================================================== */

#[derive(Clone)]
struct Agent {
    pk: [u8; 32],
    max_per_spend: i64,
    period_budget: i64,
    period_length_daa: i64,
    period_start_daa: i64,
    period_spent: i64,
    approval_threshold: i64,
    max_fee_per_tx: i64,
    recipient_root: [u8; 32],
}
fn agent_leaf(a: &Agent) -> [u8; 32] {
    sha256(&[
        &AGENT_DOMAIN,
        &a.pk,
        &num8(a.max_per_spend),
        &num8(a.period_budget),
        &num8(a.period_length_daa),
        &num8(a.period_start_daa),
        &num8(a.period_spent),
        &num8(a.approval_threshold),
        &num8(a.max_fee_per_tx),
        &a.recipient_root,
    ])
}
fn agent(k: &Keypair, cap: i64, budget: i64, threshold: i64, fee_cap: i64) -> Agent {
    Agent {
        pk: xonly32(k),
        max_per_spend: cap,
        period_budget: budget,
        period_length_daa: 864_000,
        period_start_daa: 541_000_000,
        period_spent: 0,
        approval_threshold: threshold,
        max_fee_per_tx: fee_cap,
        recipient_root: ZERO32,
    }
}

#[allow(clippy::too_many_arguments)]
struct Spend<'a> {
    prev: VaultState,
    tree_agents: Vec<Agent>,
    target: usize,
    claim: Agent,
    pay: i64,
    reserve_consumed: i64,
    periods_elapsed: i64,
    recip_depth: u32,
    signer: &'a Keypair,
    signer_type: SigHashType,
    recipient: &'a Keypair,
    recipient_out_override: Option<[u8; 32]>,
    approver_sigs: [Option<(&'a Keypair, SigHashType)>; N_APPROVERS],
    override_new_root: Option<[u8; 32]>,
    override_succ_value: Option<i64>,
    ext_in: Option<i64>,
    ext_out: Option<i64>,
    budget: u16,
    seq_override: Option<u64>,
    lock_override: Option<u64>,
    succ_protected_override: Option<i64>,
    root_rider: bool,
    post_sign_bump_recipient: Option<i64>,
    forge_agent_sig_gate_byte: bool,
}
fn dflt<'a>(prev: VaultState, agents: Vec<Agent>, target: usize, claim: Agent, signer: &'a Keypair, recipient: &'a Keypair) -> Spend<'a> {
    Spend {
        prev,
        tree_agents: agents,
        target,
        claim,
        pay: 40 * KAS,
        reserve_consumed: 5_000_000,
        periods_elapsed: 0,
        recip_depth: 0,
        signer,
        signer_type: SIG_HASH_ALL,
        recipient,
        recipient_out_override: None,
        approver_sigs: Default::default(),
        override_new_root: None,
        override_succ_value: None,
        ext_in: None,
        ext_out: None,
        budget: 400,
        seq_override: None,
        lock_override: None,
        succ_protected_override: None,
        root_rider: false,
        post_sign_bump_recipient: None,
        forge_agent_sig_gate_byte: false,
    }
}

struct SpendOutcome {
    result: Result<(), TxScriptError>,
    units: u64,
    redeem_len: usize,
    state_region_len: usize,
    sigscript_len: usize,
    tx: Transaction,
    entries: Vec<UtxoEntry>,
}

fn run_full(c: Spend) -> SpendOutcome {
    let recovery_pk = default_recovery_pk();
    let rpin = default_root_pin();

    let (rroot, rsibs, rbits) = recip_tree(c.recip_depth, &xonly32(c.recipient));
    let mut real = c.tree_agents.clone();
    real[c.target].recipient_root = rroot;
    let real_leaves: Vec<[u8; 32]> = real.iter().map(agent_leaf).collect();
    let (root, policy_sibs, policy_bits) = merkle(&real_leaves, c.target);
    let prev = VaultState { agent_root: root, ..c.prev.clone() };

    let claim = Agent { recipient_root: rroot, ..c.claim.clone() };

    let mut new_start = claim.period_start_daa;
    let mut new_spent = claim.period_spent + c.pay;
    if c.periods_elapsed >= 1 {
        new_start = claim.period_start_daa + c.periods_elapsed * claim.period_length_daa;
        new_spent = c.pay;
    }
    let mut np = claim.clone();
    np.period_start_daa = new_start;
    np.period_spent = new_spent;
    let new_root = c.override_new_root.unwrap_or_else(|| fold(agent_leaf(&np), &policy_sibs, policy_bits));

    let new_protected = c.succ_protected_override.unwrap_or(prev.protected - c.pay);
    let new_reserve = prev.reserve - c.reserve_consumed;
    let succ = VaultState { protected: new_protected, reserve: new_reserve, agent_root: new_root, ..prev.clone() };
    let active = compile_vault(&rpin, &recovery_pk, &prev);
    let succ_c = compile_vault(&rpin, &recovery_pk, &succ);
    let succ_value = c.override_succ_value.unwrap_or(new_protected + new_reserve);

    let cov_val = prev.protected + prev.reserve;
    let mut input_ids: Vec<(u8, u64)> = vec![(0x42, c.seq_override.unwrap_or(0))];
    let mut entries = vec![cov_utxo(cov_val, &active, COV_VAULT)];

    let mut ext_pk: Option<[u8; 32]> = None;
    if let Some(ev) = c.ext_in {
        let ext_kp = kp(0x71);
        let epk = xonly32(&ext_kp);
        entries.push(UtxoEntry::new(ev as u64, p2pk_spk(&epk), 0, false, None));
        input_ids.push((0x71, 0));
        ext_pk = Some(epk);
    }

    let root_prev_c = compile_root(&RootState::with(3, 2, 1, 2), &RootTemplate::default());
    let root_succ_state = RootState::with(3, 2, 1, 2).advanced();
    let root_next_c = compile_root(&root_succ_state, &RootTemplate::default());
    if c.root_rider {
        entries.push(cov_utxo(ROOT_KAS, &root_prev_c, COV_ROOT));
        input_ids.push((0x99, 0));
    }

    let recip_out = c.recipient_out_override.unwrap_or(xonly32(c.recipient));
    let mut outputs = vec![p2pk_out(&recip_out, c.pay), cov_out(succ_value, &succ_c, 0, COV_VAULT)];
    if let Some(ov) = c.ext_out {
        let change_pk = ext_pk.unwrap_or(recip_out);
        outputs.push(p2pk_out(&change_pk, ov));
    }
    if c.root_rider {
        let root_input_idx = (input_ids.len() - 1) as u16;
        outputs.push(cov_out(ROOT_KAS - ROOT_FEE_PAID, &root_next_c, root_input_idx, COV_ROOT));
    }

    let lock = c.lock_override.unwrap_or(if c.periods_elapsed >= 1 { new_start as u64 } else { 0 });
    let unsigned = Transaction::new(
        1,
        input_ids.iter().map(|(id, seq)| tx_input(*id, vec![], *seq, c.budget)).collect(),
        outputs.clone(),
        lock,
        SubnetworkId::default(),
        0,
        vec![],
    );

    let mut agent_sig = sign_type(&unsigned, &entries, 0, c.signer, c.signer_type);
    if c.forge_agent_sig_gate_byte {
        // Sign with a genuine SIG_HASH_ALL (0x01) signature, then corrupt only
        // the trailing gate byte in the SUPPLIED call argument. requireAgentAuthorization
        // must read the actual trailing byte of the blob it is given, not merely
        // trust that a real signature was computed.
        assert_eq!(agent_sig.len(), 65, "sanity: agent_sig must be exactly 65 bytes before forging");
        assert_eq!(agent_sig[64], 0x01, "sanity: forging test must start from a real SIG_HASH_ALL signature");
        agent_sig[64] = 0x02;
    }
    let mut blob = Vec::with_capacity(650);
    for slot in c.approver_sigs.iter() {
        match slot {
            Some((k, ty)) => blob.extend_from_slice(&sign_type(&unsigned, &entries, 0, k, *ty)),
            None => blob.extend_from_slice(&placeholder_slot()),
        }
    }
    let args = vec![
        vault_state_arg(&succ),
        Expr::int(c.pay),
        Expr::bytes(claim.pk.to_vec()),
        Expr::int(claim.max_per_spend),
        Expr::int(claim.period_budget),
        Expr::int(claim.period_length_daa),
        Expr::int(claim.period_start_daa),
        Expr::int(claim.period_spent),
        Expr::int(claim.approval_threshold),
        Expr::int(claim.max_fee_per_tx),
        Expr::bytes(rroot.to_vec()),
        Expr::bytes(policy_sibs.clone()),
        Expr::int(policy_bits as i64),
        Expr::int(c.periods_elapsed),
        Expr::bytes(xonly32(c.recipient).to_vec()),
        Expr::bytes(rsibs),
        Expr::int(rbits as i64),
        Expr::bytes(agent_sig),
        Expr::bytes(blob),
    ];
    let ctrl_ss = cov_call(&active, "agentSpend", args);
    let sigscript_len = ctrl_ss.len();

    let mut sigscripts: Vec<Vec<u8>> = input_ids.iter().map(|_| vec![]).collect();
    sigscripts[0] = ctrl_ss;
    if let Some(i) = input_ids.iter().position(|(id, _)| *id == 0x71) {
        let ext_sig = sign_type(&unsigned, &entries, i, &kp(0x71), SIG_HASH_ALL);
        sigscripts[i] = p2pk_sigscript(ext_sig);
    }
    if c.root_rider {
        let i = input_ids.iter().position(|(id, _)| *id == 0x99).unwrap();
        let blob = root_owner_blob(&unsigned, &entries, i, &[0, 1]);
        sigscripts[i] = cov_call(&root_prev_c, "rootAction", vec![root_state_arg(&root_succ_state), Expr::int(0), Expr::bytes(blob)]);
    }

    let inputs: Vec<TransactionInput> =
        input_ids.iter().zip(sigscripts).map(|((id, seq), ss)| tx_input(*id, ss, *seq, c.budget)).collect();
    let mut tx = build_tx(inputs, outputs);
    tx.lock_time = lock;
    if let Some(delta) = c.post_sign_bump_recipient {
        tx.outputs[0].value = (tx.outputs[0].value as i64 + delta) as u64;
    }

    let (result, units) = execute_input_measured(tx.clone(), entries.clone(), 0);
    SpendOutcome { result, units, redeem_len: active.script.len(), state_region_len: active.state_layout.len, sigscript_len, tx, entries }
}

fn run(c: Spend) -> (Result<(), TxScriptError>, u64) {
    let o = run_full(c);
    (o.result, o.units)
}

