#[test]
fn v7kas_honest_delegate_spend() {
    let a = kp(0x30);
    let recipient = kp(0x40);
    let pa = agent(&a, 100 * KAS, 500 * KAS, 100_000 * KAS, 1 * KAS);
    let o = run_full(dflt(base_vault_state(ZERO32), vec![pa.clone()], 0, pa, &a, &recipient));
    o.result.as_ref().unwrap_or_else(|e| panic!("rooted v0.7-kas delegate spend must accept: {e:?}"));
    println!("V7KAS delegate spend: units {} | redeem {} B | state {} B | sigscript {} B", o.units, o.redeem_len, o.state_region_len, o.sigscript_len);
}

#[test]
fn v7kas_honest_delegate_spend_with_period_rollover() {
    let a = kp(0x30);
    let recipient = kp(0x40);
    let mut pa = agent(&a, 200 * KAS, 500 * KAS, 100_000 * KAS, 1 * KAS);
    pa.period_spent = 480 * KAS;
    let r = run(Spend { pay: 40 * KAS, periods_elapsed: 1, ..dflt(base_vault_state(ZERO32), vec![pa.clone()], 0, pa, &a, &recipient) }).0;
    assert!(r.is_ok(), "period rollover resets spent: {r:?}");
}

#[test]
fn v7kas_honest_delegate_spend_at_production_proof_depths() {
    let a = kp(0x30);
    let recipient = kp(0x40);
    let pa = agent(&a, 200 * KAS, 500 * KAS, 100_000 * KAS, 1 * KAS);
    let n = 1usize << 12;
    let mut agents = vec![pa.clone()];
    for i in 1..n {
        let mut g = agent(&kp(((i % 200) + 2) as u8), 1 * KAS, 1 * KAS, 1, 1);
        g.recipient_root = sha256(&[b"f", &(i as u64).to_le_bytes()]);
        agents.push(g);
    }
    let o = run_full(Spend { recip_depth: 16, budget: 800, ..dflt(base_vault_state(ZERO32), agents, 0, pa, &a, &recipient) });
    o.result.as_ref().unwrap_or_else(|e| panic!("deep proofs (agent 12 / recipient 16) must accept: {e:?}"));
    println!("V7KAS delegate spend at depths agent 12 / recipient 16: units {} | sigscript {} B", o.units, o.sigscript_len);
}

#[test]
fn v7kas_valid_matrix_agent_and_recipient_depths() {
    let a = kp(0x30);
    let recipient = kp(0x40);
    for adepth in [0u32, 1, 4, 8, 12] {
        let pa = agent(&a, 200 * KAS, 500 * KAS, 100_000 * KAS, 1 * KAS);
        let n = 1usize << adepth;
        let mut agents = vec![pa.clone()];
        for i in 1..n {
            let mut g = agent(&kp(((i % 200) + 2) as u8), 1 * KAS, 1 * KAS, 1, 1);
            g.recipient_root = sha256(&[b"f", &(i as u64).to_le_bytes()]);
            agents.push(g);
        }
        let r = run(dflt(base_vault_state(ZERO32), agents, 0, pa, &a, &recipient)).0;
        assert!(r.is_ok(), "agent depth {adepth} valid: {r:?}");
    }
    for rdepth in [0u32, 1, 4, 8, 12, 16] {
        let pa = agent(&a, 200 * KAS, 500 * KAS, 100_000 * KAS, 1 * KAS);
        let r = run(Spend { recip_depth: rdepth, ..dflt(base_vault_state(ZERO32), vec![pa.clone()], 0, pa, &a, &recipient) }).0;
        assert!(r.is_ok(), "recipient depth {rdepth} valid: {r:?}");
    }
}

#[test]
fn v7kas_threshold_and_approvals_positive() {
    let a = kp(0x30);
    let (a1, a2, a3) = (kp(0x20), kp(0x21), kp(0x22));
    let recipient = kp(0x40);
    let slots = approver_set(&[&a1, &a2, &a3]);
    let mut st = base_vault_state(ZERO32);
    st.approvers = slots;
    st.approval_m = 2;
    let pa = agent(&a, 200 * KAS, 500 * KAS, 50 * KAS, 1 * KAS);
    assert!(run(Spend { pay: 50 * KAS, ..dflt(st.clone(), vec![pa.clone()], 0, pa.clone(), &a, &recipient) }).0.is_ok(), "at threshold: delegate-only");
    let ap = approvals_by_key(&slots, &[(&a1, SIG_HASH_ALL), (&a2, SIG_HASH_ALL)]);
    assert!(run(Spend { pay: 150 * KAS, approver_sigs: ap, ..dflt(st, vec![pa.clone()], 0, pa, &a, &recipient) }).0.is_ok(), "2-of-3 approvals above threshold");
}

#[test]
fn v7kas_worst_case_stack_and_execute() {
    let a = kp(0x1e);
    let recipient = kp(0x28);
    let approvers: Vec<Keypair> = (0..10).map(|i| kp(0x3c + i)).collect();
    let arefs: Vec<&Keypair> = approvers.iter().collect();
    let slots = approver_set(&arefs);
    let pa = agent(&a, 200 * KAS, 500 * KAS, 50 * KAS, 1 * KAS);
    let n = 1usize << 12;
    let mut agents = vec![pa.clone()];
    for i in 1..n {
        agents.push(agent(&kp(((i % 200) + 2) as u8), 1 * KAS, 1 * KAS, 1, 1));
    }
    for (i, g) in agents.iter_mut().enumerate().skip(1) {
        g.recipient_root = sha256(&[b"filler", &(i as u64).to_le_bytes()]);
    }
    let mut st = base_vault_state(ZERO32);
    st.approvers = slots;
    st.approval_m = 10;
    let signers: Vec<(&Keypair, SigHashType)> = approvers.iter().map(|k| (k, SIG_HASH_ALL)).collect();
    let ap = approvals_by_key(&slots, &signers);
    let o = run_full(Spend { pay: 150 * KAS, recip_depth: 16, approver_sigs: ap, budget: 800, ..dflt(st, agents, 0, pa, &a, &recipient) });
    o.result.as_ref().unwrap_or_else(|e| panic!("WORST CASE depth12+recip16+10of10 must execute under MAX_STACK_SIZE 244: {e:?}"));
    println!("V7KAS WORST depth12+recip16+10of10: compute_units={}", o.units);
}

