#[test]
fn v7kas_delegate_forged_successor_root_rejected() {
    let a = kp(0x30);
    let b = kp(0x31);
    let recipient = kp(0x40);
    let pa = agent(&a, 100 * KAS, 500 * KAS, 100_000 * KAS, 1 * KAS);
    let pb = agent(&b, 1000 * KAS, 10_000 * KAS, 100_000 * KAS, 5 * KAS);
    let leaves = vec![agent_leaf(&{ let mut g = pa.clone(); g.recipient_root = recip_tree(0, &xonly32(&recipient)).0; g }), agent_leaf(&pb)];
    let orig = merkle(&leaves, 0).0;
    let r = run(Spend { pay: 80 * KAS, override_new_root: Some(orig), ..dflt(base_vault_state(ZERO32), vec![pa.clone(), pb], 0, pa, &a, &recipient) }).0;
    assert_rejected(r, "forged (unchanged) successor root must be refused");
}

#[test]
fn v7kas_delegate_approval_shortfall_and_nonapprover_signature_rejected() {
    let a = kp(0x30);
    let (a1, a2, a3) = (kp(0x20), kp(0x21), kp(0x22));
    let recipient = kp(0x40);
    let slots = approver_set(&[&a1, &a2, &a3]);
    let mut st = base_vault_state(ZERO32);
    st.approvers = slots;
    st.approval_m = 2;
    let pa = agent(&a, 200 * KAS, 500 * KAS, 50 * KAS, 1 * KAS);

    let ap1 = approvals_by_key(&slots, &[(&a1, SIG_HASH_ALL)]);
    assert_rejected(run(Spend { pay: 150 * KAS, approver_sigs: ap1, ..dflt(st.clone(), vec![pa.clone()], 0, pa.clone(), &a, &recipient) }).0, "1-of-2 approvals (shortfall) must be refused");

    let ap_wrong = {
        let mut ap: [Option<(&Keypair, SigHashType)>; N_APPROVERS] = Default::default();
        ap[0] = Some((&a, SIG_HASH_ALL)); // a's OWN key does not hold slot 0 (a1 does)
        ap[1] = Some((&a2, SIG_HASH_ALL));
        ap
    };
    assert_rejected(run(Spend { pay: 150 * KAS, approver_sigs: ap_wrong, ..dflt(st, vec![pa.clone()], 0, pa, &a, &recipient) }).0, "a non-approver signature placed in an approver slot must not count");
}

#[test]
fn v7kas_delegate_malformed_genesis_duplicate_approver_rejected() {
    let a = kp(0x30);
    let k = kp(0x23);
    let a3 = kp(0x22);
    let recipient = kp(0x40);
    let pa = agent(&a, 200 * KAS, 500 * KAS, 50 * KAS, 1 * KAS);
    let mut approvers = [ZERO32; N_APPROVERS];
    approvers[0] = xonly32(&k);
    approvers[1] = xonly32(&k);
    approvers[2] = xonly32(&a3);
    let mut st = base_vault_state(ZERO32);
    st.approvers = approvers;
    st.approval_m = 2;
    let mut ap: [Option<(&Keypair, SigHashType)>; N_APPROVERS] = Default::default();
    ap[0] = Some((&k, SIG_HASH_ALL));
    ap[1] = Some((&k, SIG_HASH_ALL));
    let r = run(Spend { pay: 150 * KAS, approver_sigs: ap, ..dflt(st, vec![pa.clone()], 0, pa, &a, &recipient) }).0;
    assert_rejected(r, "duplicate predecessor approver key must be refused (A2 malformed-genesis defense)");
}

