#[test]
fn v7kas_delegate_fee_domain_and_value_leakage_matrix() {
    let a = kp(0x30);
    let recipient = kp(0x40);
    let other = kp(0x41);
    let pa = agent(&a, 100 * KAS, 500 * KAS, 100_000 * KAS, 1 * KAS);
    let base = base_vault_state(ZERO32);
    let mk = |f: &dyn Fn(&mut Spend)| {
        let mut sp = dflt(base_vault_state(ZERO32), vec![pa.clone()], 0, pa.clone(), &a, &recipient);
        f(&mut sp);
        run(sp).0
    };
    assert_rejected(mk(&|s| { s.reserve_consumed = 0; s.override_succ_value = Some(base.protected - s.pay + base.reserve - 5_000_000); }), "principal used as fee");
    assert_rejected(mk(&|s| { s.reserve_consumed = 1 * KAS; s.ext_out = Some(1 * KAS); }), "reserve redirected to an external output");
    assert_rejected(mk(&|s| { s.reserve_consumed = 1 * KAS; s.ext_in = Some(50_000_000); s.ext_out = Some(1 * KAS + 50_000_000); }), "external input masks reserve theft");
    assert_rejected(mk(&|s| { s.reserve_consumed = 0; s.ext_out = Some(3 * KAS); }), "external output exceeds external input");
    assert_rejected(mk(&|s| { s.reserve_consumed = 2 * KAS; s.ext_in = Some(3 * KAS); s.ext_out = Some(1 * KAS); }), "reserve consumption above the agent's fee cap");
    assert_rejected(mk(&|s| { s.pay = 0; }), "zero payment");
    assert_rejected(mk(&|s| { s.pay = 101 * KAS; }), "payment above cap");
    assert_rejected(mk(&|s| { s.reserve_consumed = -1 * KAS; }), "reserve consumption forged negative (value leakage)");
    assert_rejected(mk(&|s| { s.reserve_consumed = -s.pay; }), "principal-to-reserve swap (value leakage)");
    assert_rejected(mk(&|s| { s.recipient_out_override = Some(xonly32(&other)); }), "recipient substitution");
    assert!(mk(&|s| { s.reserve_consumed = 1 * KAS; s.ext_in = Some(2 * KAS); s.ext_out = Some(1 * KAS); }).is_ok(), "consuming exactly the fee cap with external change must accept");
}

