/* --- v0.7-kas candidate hardening E6(b): agentSpend now REFUSES any
 * covenant rider on the delegate path (requireOnlyPlainInputsOnDelegatePath).
 * UNLIKE frozen v0.4.1's agentSpend (which has no foreign-covenant-family
 * check at all — it predates multiple covenant families coexisting in one
 * PolicyVault transaction) this profile closes the surface unconditionally,
 * for parity with the payment profile's own family-isolation shape
 * (requireNoForeignCovenantInputs) even though a root rider was already
 * VERIFIED SAFE under the old (inherited) behavior — this is defense in
 * depth, not a bug fix. */

#[test]
fn v7kas_delegate_spend_refuses_a_root_covenant_rider() {
    let a = kp(0x30);
    let recipient = kp(0x40);
    let pa = agent(&a, 100 * KAS, 500 * KAS, 100_000 * KAS, 1 * KAS);
    let r = run(Spend { root_rider: true, ..dflt(base_vault_state(ZERO32), vec![pa.clone()], 0, pa, &a, &recipient) }).0;
    assert_rejected(r, "E6(b): agentSpend must refuse a root-covenant rider on the delegate path");
}

#[test]
fn v7kas_delegate_spend_positive_control_no_rider_still_accepts() {
    // Positive control paired with the refusal above: the SAME honest spend,
    // with root_rider left false, must still accept — proving the new
    // requireOnlyPlainInputsOnDelegatePath() closure does not over-refuse the
    // ordinary (no-rider) delegate path.
    let a = kp(0x30);
    let recipient = kp(0x40);
    let pa = agent(&a, 100 * KAS, 500 * KAS, 100_000 * KAS, 1 * KAS);
    let r = run(Spend { root_rider: false, ..dflt(base_vault_state(ZERO32), vec![pa.clone()], 0, pa, &a, &recipient) }).0;
    assert!(r.is_ok(), "positive control: an ordinary delegate spend with no rider must still accept: {r:?}");
}

/* --- v0.7-kas candidate hardening E6(a): agentSpend now requires the
 * agent's OWN signature to be SIG_HASH_ALL (requireAgentAuthorization),
 * exact parity with the ALREADY-PROVEN gate in
 * contracts/PolicyVault.v0.6.sil. UNLIKE frozen v0.4.1's agentSpend and the
 * frozen v0.7-payment profile's tokenAgentSpend (both carry an UNGATED `sig`
 * parameter — documented, verified-safe there because the outputs are bound
 * structurally regardless of what the signature covers), this profile closes
 * the surface unconditionally. */

#[test]
fn v7kas_delegate_spend_refuses_non_all_agent_sighash() {
    let a = kp(0x30);
    let recipient = kp(0x40);
    let pa = agent(&a, 100 * KAS, 500 * KAS, 100_000 * KAS, 1 * KAS);
    let anyone_can_pay_single =
        SigHashType::from_u8(SIG_HASH_SINGLE.to_u8() | SIG_HASH_ANY_ONE_CAN_PAY.to_u8()).expect("allowed sighash type");
    for (label, ty) in [("SIGHASH_NONE", SIG_HASH_NONE), ("SIGHASH_SINGLE|ANYONECANPAY", anyone_can_pay_single)] {
        let r = run(Spend {
            signer_type: ty,
            ..dflt(base_vault_state(ZERO32), vec![pa.clone()], 0, pa.clone(), &a, &recipient)
        })
        .0;
        assert_rejected(r, &format!("E6(a): agentSpend must refuse a non-SIG_HASH_ALL agent signature ({label})"));
    }
}

#[test]
fn v7kas_delegate_spend_refuses_a_forged_gate_byte() {
    // The A7-style gate checks the LAST byte of the 65-byte agentSig blob
    // (SIG_HASH_ALL == 0x01). Sign with a real SIG_HASH_ALL signature (so the
    // 64-byte signature body itself is genuinely valid) and then forge only
    // the trailing byte in the call argument — the covenant must still
    // refuse, proving the gate reads the ACTUAL trailing byte of the
    // supplied blob and is not satisfied merely because the underlying
    // signature was computed over the ALL sighash.
    let a = kp(0x30);
    let recipient = kp(0x40);
    let pa = agent(&a, 100 * KAS, 500 * KAS, 100_000 * KAS, 1 * KAS);
    let o = run_full(Spend {
        forge_agent_sig_gate_byte: true,
        ..dflt(base_vault_state(ZERO32), vec![pa.clone()], 0, pa, &a, &recipient)
    });
    assert_rejected(o.result, "E6(a): agentSpend must refuse a forged (non-0x01) trailing gate byte even over an ALL-computed signature");
}

#[test]
fn v7kas_delegate_spend_positive_control_all_sighash_still_accepts() {
    // Positive control paired with the two refusals above: an ordinary
    // SIG_HASH_ALL agent signature, unmutated, must still accept.
    let a = kp(0x30);
    let recipient = kp(0x40);
    let pa = agent(&a, 100 * KAS, 500 * KAS, 100_000 * KAS, 1 * KAS);
    let r = run(Spend { signer_type: SIG_HASH_ALL, ..dflt(base_vault_state(ZERO32), vec![pa.clone()], 0, pa, &a, &recipient) }).0;
    assert!(r.is_ok(), "positive control: an ordinary SIG_HASH_ALL agent signature must still accept: {r:?}");
}

/* ================================================================== */
/* measurement, standardness, MAX_STACK_SIZE headroom                  */
/* ================================================================== */

fn mass_of(tx: &Transaction, entries: &[UtxoEntry]) -> (u64, u64, u64, u64) {
    let mc = MassCalculator::new(1, 10, STORAGE_MASS_PARAMETER);
    let m = mc.calc_non_contextual_masses(tx);
    let populated = PopulatedTransaction::new(tx, entries.to_vec());
    let storage = mc.calc_contextual_masses(&populated).map(|c| c.storage_mass).unwrap_or(0);
    let size = transaction_estimated_serialized_size(tx) as u64;
    (size, m.compute_mass, m.transient_mass, storage)
}

fn priced_units_and_sigops(tx: &Transaction, entries: &[UtxoEntry]) -> Vec<(u64, u16, u64)> {
    (0..tx.inputs.len())
        .map(|i| {
            let (r, priced) = execute_input_measured_priced(tx.clone(), entries.to_vec(), i, 1000);
            r.unwrap_or_else(|e| panic!("priced input {i} must accept: {e:?}"));
            let budget = ComputeBudget::checked_covering_script_units(ScriptUnits(priced)).expect("budget").0;
            let sigops = post_toccata_p2sh_sig_scanner(&tx.inputs[i].signature_script, &entries[i].script_public_key);
            (priced, budget, sigops)
        })
        .collect()
}

const MAX_STACK_PROBE: usize = 244;

fn measure_peak_stack<F>(label: &str, mut run_with_pad: F) -> usize
where
    F: FnMut(usize) -> Result<(), TxScriptError>,
{
    run_with_pad(0).unwrap_or_else(|e| panic!("{label}: unpadded run must accept: {e:?}"));
    for pad in 1..=MAX_STACK_PROBE {
        if let Err(TxScriptError::StackSizeExceeded(size, max)) = run_with_pad(pad) {
            assert_eq!(max, 244, "{label}: unexpected MAX_STACK_SIZE");
            let peak = 245 - pad;
            println!("  {label}: peak combined stack {peak} (StackSizeExceeded at pad {pad}, reported {size}/{max}) -> headroom {}", 244 - peak);
            return peak;
        }
    }
    panic!("{label}: never hit MAX_STACK_SIZE within {MAX_STACK_PROBE} padding items");
}

fn check_standardness(label: &str, tx: &Transaction, entries: &[UtxoEntry], compute: u64, transient: u64) {
    for i in 0..tx.inputs.len() {
        let ops = post_toccata_p2sh_sig_scanner(&tx.inputs[i].signature_script, &entries[i].script_public_key);
        assert!(ops <= MAX_STANDARD_P2SH_SIG_OPS, "{label}: input {i} static sig-ops {ops} must be <= 15 (standard)");
    }
    for (i, o) in tx.outputs.iter().enumerate() {
        assert_ne!(ScriptClass::from_script(&o.script_public_key), ScriptClass::NonStandard, "{label}: output {i} must be a standard class");
    }
    assert!(compute <= 500_000, "{label}: compute mass {compute} exceeds the post-Toccata block-fit limit");
    assert!(transient <= 1_000_000, "{label}: transient mass {transient} exceeds the post-Toccata block-fit limit");
    if transient > 100_000 || compute > 100_000 {
        println!("    note: {label} exceeds the PRE-Toccata 100,000 standard cap — post-Toccata only");
    }
}

